// The public paths of std, core, and alloc 1.99 (x86_64 Linux), for
// std imports lust has no binding for: a path std has stays accepted
// (an unused import of it is valid Rust), any other path is unresolved
// (L0506, rustc E0432). Read only for such imports, so the table is
// parsed per query.
//
// `std_paths.txt` is generated by tools/std-paths/gen.sh (rustc as the
// oracle: every module walked with a glob import and one
// `use self::Name as _;` probe per candidate name, then one
// `use path::Name::{};` probe per type name to find the traits). Format: one line
// per module, `<module path> <item>...`, where an item is a name with
// an optional kind suffix: `/m` a module (it has its own line), `/e`
// an enum (its variants follow on a line of their own, like a
// module's items), `/t` a trait. A line `<path> = <other path>` says the module has
// exactly the items of the other one (std re-exports most of core).

const TABLE: &str = include_str!("std_paths.txt");

/// What std has at a full path.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum StdHas {
    /// A module (a glob of it imports its items).
    Module,
    /// An enum (a glob of it imports its variants).
    Enum,
    /// A trait: `use path::Trait::{self};` works, a glob does not.
    Trait,
    /// Any other item: a type, trait, fn, const, static, macro, or variant.
    Item,
}

/// The items line of the module or enum at `path`, after `=` links.
fn items_of(path: &str) -> Option<&'static str> {
    let mut want = path.to_string();
    for _ in 0..8 {
        let line = TABLE.lines().find(|l| l.split(' ').next() == Some(want.as_str()))?;
        let rest = line[want.len()..].trim_start();
        match rest.strip_prefix("= ") {
            Some(other) => want = other.trim().to_string(),
            None => return Some(rest),
        }
    }
    None
}

/// What std 1.99 has at `path` (`["std", "task", "Poll"]`), or None.
pub fn std_has(path: &[&str]) -> Option<StdHas> {
    match path {
        [] => None,
        [root] => matches!(*root, "std" | "core" | "alloc").then_some(StdHas::Module),
        [parent @ .., last] => {
            let items = items_of(&parent.join("::"))?;
            items.split(' ').find_map(|it| {
                let (name, kind) = it.split_once('/').unwrap_or((it, ""));
                (name == *last).then_some(match kind {
                    "m" => StdHas::Module,
                    "e" => StdHas::Enum,
                    "t" => StdHas::Trait,
                    _ => StdHas::Item,
                })
            })
        }
    }
}

#[cfg(test)]
mod tests {
    use super::{StdHas, std_has};

    fn has(p: &str) -> Option<StdHas> {
        std_has(&p.split("::").collect::<Vec<_>>())
    }

    #[test]
    fn real_paths_and_kinds() {
        assert_eq!(has("std"), Some(StdHas::Module));
        assert_eq!(has("std::collections"), Some(StdHas::Module));
        assert_eq!(has("std::collections::HashMap"), Some(StdHas::Item));
        assert_eq!(has("std::collections::hash_map::HashMap"), Some(StdHas::Item));
        assert_eq!(has("std::task::Poll"), Some(StdHas::Enum));
        assert_eq!(has("std::cmp::Ord"), Some(StdHas::Trait));
        assert_eq!(has("core::fmt::Write"), Some(StdHas::Trait));
        assert_eq!(has("std::rc::Rc"), Some(StdHas::Item));
        assert_eq!(has("core::task::Poll::Ready"), Some(StdHas::Item));
        assert_eq!(has("std::mem::offset_of"), Some(StdHas::Item));
        assert_eq!(has("std::os::unix::fs::OpenOptionsExt"), Some(StdHas::Trait));
        assert_eq!(has("std::arch::x86_64::_mm_add_ps"), Some(StdHas::Item));
        assert_eq!(has("std::arch::x86_64::Lines"), None);
    }

    #[test]
    fn missing_paths() {
        assert_eq!(has("std::task::Nonexistent"), None);
        assert_eq!(has("std::nosuchmod::Foo"), None);
        assert_eq!(has("core::collections::HashMap"), None);
        assert_eq!(has("core::fs::File"), None);
        assert_eq!(has("std::collections::Nope"), None);
        assert_eq!(has("lust::x"), None);
    }
}
